  "C_third_party_type": "辛提供的是有效的一般保证，而非债务加入；其责任为依法强制执行乙后仍不能清偿部分的50%，保留先诉抗辩。",
  "C_third_party_payment_limit": "0.00",
  "basis": {
    "A的效力与返还": {
      "facts": ["dossier.md[S01]", "dossier.md[S02]", "dossier.md[S12]"],
      "rules": [
        "lending-2020-12第13、31条",
        "civil-code-2020第157、682条"
      ],
      "explanation": "A于2022年成立，适用现行套取金融机构贷款转贷即无效的规则，不适用lending-2015第14条中高利转贷及借款人知情的旧条件。乙仅须返还尚未返还的实际取得财产；同交易号收据不构成另一笔交付。丁的从属保证无效，题设排除了保证无效后的赔偿请求。",
      "calculation": "143106.00－20284.00＝122822.00元。"
    },
    "B合同及本息清算": {
      "facts": ["dossier.md[S03]", "dossier.md[S04]", "dossier.md[S05]", "dossier.md[S06]"],
      "rules": [
        "civil-code-2020第670、679、680条",
        "lending-2020-12第25、26、27、28条"
      ],
      "explanation": "B借款有效。预扣利息不计入初始本金；后续借据无新增交付且不构成债务更新，须从实际本金重算合法结息，不能照搬纸面金额。约定年利率13.200%低于成立时LPR四倍14.80%，按13.200%计算，并另检验第27条整体上限。到期后继续按借期内利率计算合法资金占用利息。",
      "initial_principal_calculation": "199182.00－12522.00＝186660.00元。",
      "method": "各段按P_next＝P_current×(1＋0.132×实际日数/365)连续计算，不对中间值取分。下列六位小数仅为展示值。",
      "recalculation": [
        {
          "period": "2022-01-12至2022-07-06",
          "days": 175,
          "protected_balance_before_payment": "198473.276712"
