      "overall_cap": "总日数566；186660×(1＋0.148×566/365)＝229498.7256986301元，高于重算本息227769.3253007536元，故整体上限不触发。",
      "after_SP01": "227769.3253007536－25000.00＝202769.3253007536元，最终取分为202769.33元。"
    },
    "戊庚保证及单方抗辩": {
      "facts": ["dossier.md[S06]", "dossier.md[S12]"],
      "rules": [
        "civil-code-2020第688、691、692、693、695条",
        "guarantee-2020第13、25、29、31、32条"
      ],
      "explanation": "戊的无条件清偿及无须先向乙追索条款，以及共同原件对戊、庚全额连带保证的明确约定，均指向连带责任保证。两人均已同意合法结息机制。保证至本息还清属于期间约定不明；展期未经两人书面同意，不改变按原到期日2023-01-12计算的六个月保证期间，届满日为2023-07-12。戊案起诉状于7月7日已送达，7月9日撤诉不否定期间内行权；对庚的完整请求于7月6日独立到达，也在期间内。7月18日催告不是保全责任的唯一依据。内部各50%仅为追偿分担，不使对甲的全额责任减半；甲未遗漏向庚及时行权，戊丧失追偿权而免责的抗辩亦无事实基础。戊、庚各可被请求立即支付202769.33元，但属同一B债务，不得重复受偿。"
    },
    "C合同利率与流水清算": {
      "facts": ["dossier.md[S07]", "dossier.md[S08]", "dossier.md[S09]", "dossier.md[S11]"],
      "rules": [
        "lending-2015第26条",
        "lending-2020-12第25、28、31条",
        "civil-code-2020第561条"
      ],
      "explanation": "C借款有效。依过渡规则及甲的明确请求，成立日至2020-08-19按约定23.50%计算，该利率未超过旧规则24%保护线；2020-08-20起按题设起诉时LPR四倍，即3.25%×4＝13.00%计算，包括逾期阶段。2022年保证和2023年第三人文书不重置借款成立日或利率基准。付款顺序遵守原合同，但T-02依双方有效补充协议先清本金；其他付款中乙单方备注不足以变更顺序。T-01的重复凭证只计一次。X-01未执行、未到账，不计付款，点击提交不等于清偿。",
      "method": "每段利息＝该段未偿本金×适用年利率×实际日数/365；未付利息只结转、不生息。除T-02外，付款先费用、再依法可请求利息、最后本金。T-01先清费用1680.00元，此后费用余额均为零。以下中间值展示至六位小数，实际计算不作中间取分。",
      "ledger_columns": ["交易或截日", "本段计息日数及年利率", "付款额", "付款后本金", "付款后未付利息"],
      "ledger": [
        ["T-01／2019-04-18", "70日，23.50%", "25234.00", "214073.673973", "0.000000"],
        ["T-02／2019-08-23", "127日，23.50%", "26965.00", "187108.673973", "17504.188492"],
        ["T-03／2020-02-14", "175日，23.50%", "28696.00", "187108.673973", "9889.953471"],
        ["T-04／2020-09-21", "188日，23.50%；32日，13.00%", "30427.00", "187108.673973", "4243.318676"],
        ["T-05／2021-04-11", "202日，13.00%", "32158.00", "172655.564644", "0.000000"],
        ["T-06／2022-06-06", "421日，13.00%", "33889.00", "164655.438762", "0.000000"],
        ["T-07／2023-07-06", "395日，13.00%", "35620.00", "152199.977887", "0.000000"],
        ["2023-08-01截日", "26日，13.00%", "0.00", "152199.977887", "1409.413494"]
      ],
      "final_calculation": "本金152199.9778866111元取分为152199.98元；末段利息＝152199.9778866111×0.13×26/365＝1409.4134938541元，取分为1409.41元；费用0.00元。C分项取分后合计153609.39元。"
    },
    "己的保证": {
      "facts": ["dossier.md[S07]", "dossier.md[S10]", "dossier.md[S12]", "dossier.md[S14]"],
      "rules": [
        "civil-code-2020第1260、687、691、692、693条",
        "guarantee-2020第25、31、34条"
      ],
      "explanation": "己的保证订立于2022年，不能因主借款成立于2019年而改用旧保证规则。不能履行、无力偿还时才代偿的正文构成一般保证。未约定保证期间，按C到期日2022-12-15起六个月计算，至2023-06-15届满。6月8日起诉虽于6月12日撤回，但6月14日已在届满前重新有效起诉乙，故责任保全，己主张责任消灭不成立。5月8日单独催告己不能代替对乙起诉；6月25日仅确认收件且明确不确认付款义务，也不构成新保证，但本案原保证本已存续。乙有可执行财产、无先诉抗辩例外，C-诉2尚未审判及执行，因此己仅承担附先诉顺序的一般保证责任，不能被要求立即付款；未来实际不能清偿的金额尚未确定。"
    },
    "SP01的抵充": {
      "facts": ["dossier.md[S06]", "dossier.md[S10]", "dossier.md[S13]", "dossier.md[S14]"],
      "rules": ["civil-code-2020第560、561条"],
      "explanation": "SP-01于09:20实际到账，约定仅清偿B、C，不清偿A。此时B、C均已到期，戊、庚及己的保证责任均依法存续，具备附件约定的同等资信全额保证条件。按付款日依法可强制请求的年利率比较，B为13.20%，C为13.00%，故25000元全部先抵B，不能用C票面23.50%比较。13:40才形成的辛文书不能追溯改变已经完成的抵充，也没有相应重新抵充约定，乙的反向主张不成立。",
      "within_B": "B当期未付利息15649.2324909134元先受偿；余款9350.7675090866元抵本金。抵充后B利息余额为零、合法本金余额为202769.3253007536元。C余额不因SP-01减少。"
    },
    "辛文书的法律状态及范围": {
      "facts": ["dossier.md[S12]", "dossier.md[S14]"],
      "rules": [
        "guarantee-2020第25、36条",
        "civil-code-2020第552、687、691、692、693、697条"
      ],
      "explanation": "应依正文而非《代偿支持》标题分类。辛明确要求甲先向乙追索并强制执行，仅对之后仍不能清偿部分支付50%，又保留先诉权，属于一般保证，不是共同承担现时债务的债务加入。约定责任期间为2023-08-01至2024-02-01；同日16:10已获准在仍向乙追索的C-诉2中追加辛。该诉讼行为不等于已经完成对乙的审判和执行，且不存在先诉抗辩例外，故甲要求辛立即支付不获支持。文书没有免除乙债务，也不使己原全额一般保证减半。",
      "scope_calculation": "约定基数＝152199.98＋1409.41＋0.00＝153609.39元；该基数50%四舍五入为76804.70元，其余数额＝153609.39－76804.70＝76804.69元。76804.70元是全部基数未获清偿时辛的最高保证份额，不是当前立即支付额；实际责任仍限于依法执行后未清偿部分的50%。"
    },
    "结算及汇总": {
      "facts": ["dossier.md[S04]", "dossier.md[S07]", "dossier.md[S12]", "dossier.md[S13]", "dossier.md[S14]"],
      "explanation": "结算包括8月1日已到账的SP-01，但不计8月1日当日利息。最终分项各自四舍五入到分后汇总；保证责任与第三人责任不重复计入乙的债务总额。不计算题设排除的赔偿、其他请求或合并程序问题。",
      "calculation": "乙的总额＝122822.00＋202769.33＋152199.98＋1409.41＋0.00＝479200.72元。"
    }
  }
}
